<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Infrastructure\Driven;

use Override;
use Throwable;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Infrastructure\Connector\Pdo\UserFederatedIdentityPdoConnector;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentitySlide;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityFilter;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityCursor;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentityRef;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentity;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserFederatedIdentityQueryRepositoryAdapter implements UserFederatedIdentityQueryRepositoryGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly UserFederatedIdentityPdoConnector $conn,
    ) {
    }
    #[Override]
    public function resolve(UserFederatedIdentityRef $ref): ?UserFederatedIdentity
    {
        if ($ref instanceof UserFederatedIdentity) {
            return $ref;
        } elseif (!$ref->_private_resolve) {
            $ref->_private_resolve = $this->conn->retrieve(new UserFederatedIdentityFilter(uids: [ $ref->uid() ]));
        }
        return $ref->_private_resolve;
    }
    #[Override]
    public function list(?UserFederatedIdentityFilter $filter = null, ?UserFederatedIdentityCursor $cursor = null): UserFederatedIdentitySlide
    {
        $this->logDebug("List for User federated identity on adapter ");
        $span = $this->startSpan("List for User federated identity on adapter");
        try {
            $lookahead = null === $cursor ? 0 : max(1, (int) ceil($cursor->limit() * 0.05));
            $values = $this->conn->list($filter, $cursor?->withLimit($cursor->limit() + $lookahead));
            return new UserFederatedIdentitySlide(fn (UserFederatedIdentitySlide $slide, UserFederatedIdentityCursor $next): UserFederatedIdentitySlide => new UserFederatedIdentitySlide(null, $next, $this->conn->list($filter, $next)), $cursor, $values, false, $lookahead);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieve(UserFederatedIdentityFilter $filter): ?UserFederatedIdentity
    {
        $this->logDebug("Retrieve for User federated identity on adapter ");
        $span = $this->startSpan("Retrieve for User federated identity on adapter");
        try {
            return $this->conn->retrieve($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function exists(UserFederatedIdentityFilter $filter): bool
    {
        $this->logDebug("Exists for User federated identity on adapter ");
        $span = $this->startSpan("Exists for User federated identity on adapter");
        try {
            return $this->conn->exists($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function count(?UserFederatedIdentityFilter $filter = null): int
    {
        $this->logDebug("Count for User federated identity on adapter ");
        $span = $this->startSpan("Count for User federated identity on adapter");
        try {
            return $this->conn->count($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneByUid(string $uid): ?UserFederatedIdentity
    {
        $this->logDebug("Find on by uid for User federated identity on adapter");
        $span = $this->startSpan("Find on by uid for User federated identity on adapter");
        try {
            return $this->conn->retrieve(new UserFederatedIdentityFilter(uids: [$uid]));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneByLoginProviderAndSubject(TenantLoginProviderRef $loginProvider, string $subject): ?UserFederatedIdentity
    {
        $this->logDebug("Find on by login provider subject for User federated identity on adapter");
        $span = $this->startSpan("Find on by login provider subject for User federated identity on adapter");
        try {
            return $this->conn->retrieve(new UserFederatedIdentityFilter(loginProviderAndSubject: UserFederatedIdentityFilter::loginProviderAndSubjectFilter(loginProvider: $loginProvider, subject: $subject)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
